/**
 * DAY-range service helpers.
 *
 * APPOINTMENT services whose schedule has a `durationRange` with
 * `unitType === DAY` route through the per-day slot path:
 *   - 1 picked slot  -> `createBooking`
 *   - 2..8 picked slots -> `createMultiServiceBooking`
 *   - 2..8 picked slots with `allDay` -> `createBooking`
 *
 * CLASS/COURSE selections and HOUR-range / fixed-duration APPOINTMENT
 * selections keep using the existing `createBooking` path.
 */
import { ServiceType, UnitType, } from '@wix/auto_sdk_bookings_services';
/**
 * Returns true when the given service is an APPOINTMENT whose duration is
 * configured as a DAY range. Useful at the UI layer (e.g. routing) to know
 * before a slot has been picked whether the selection will go through the
 * DAY-range create path.
 */
export function isDayRangeService(service) {
    const isAppointment = service.type === ServiceType.APPOINTMENT;
    const isDayRange = service.schedule?.availabilityConstraints?.durationRange?.unitType ===
        UnitType.DAY;
    return isAppointment && isDayRange;
}
/**
 * Returns the configured min/max day bounds for a DAY-range service, or
 * `null` if the service is not DAY-range. Falls back to `min = 1` / `max = min`
 * when the service is missing `dayOptions` configuration values.
 */
export function getDayRangeBounds(service) {
    if (!isDayRangeService(service))
        return null;
    const dayOptions = service.schedule?.availabilityConstraints?.durationRange?.dayOptions;
    const min = dayOptions?.minDurationInDays ?? 1;
    const max = dayOptions?.maxDurationInDays ?? min;
    if (max < min)
        return null;
    return { min, max };
}
